from taf.internal.gnb.oam.rap.client.rap.v2 import CMApi, ApiClient, Configuration, InitializeOperationRequestBody, \
    CreateEditingBufferBody, CmEditorJobPost, EditorSingleParam, CmEditorTemplateJobPost
from taf.internal.gnb.oam.rap.client.rap.v2.exceptions import ApiException
from taf.sbts.oam.sc.rest.exception import PlanFileNotFound, AsirOperationTimeout
from urllib3.util.retry import MaxRetryError
import logging
import time

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CmV1(object):

    def __init__(self, con_details, access_token):
        self.configuration = self._create_configuration_prepare(con_details)
        self.configuration.access_token = access_token
        self.cm_api_instance = CMApi(ApiClient(self.configuration))
        self._current_plan_id = None
        self._current_job_id = None

    @property
    def current_plan_id(self):
        return self._current_plan_id

    @property
    def current_job_id(self):
        return self._current_job_id

    @staticmethod
    def _create_configuration_prepare(con_details):
        config_object = Configuration()
        config_object.host = con_details.make_configuration_host(original_endpoint=config_object.host)
        config_object.retries = 0
        config_object.verify_ssl = con_details.secure
        return config_object

    def upload_plan(self, scf_path):
        try:
            with open(scf_path, "r") as scf_file:
                scf_content = scf_file.read()
            plan_id_results = self.cm_api_instance.cm_plans_staged_post(scf_content)
            self._current_plan_id = plan_id_results.id
            return plan_id_results
        except IOError:
            raise PlanFileNotFound("File '{}' not found".format(scf_path))

    def upload_plan_template(self, delta_plan_id, scf_path):
        try:
            with open(scf_path, "r") as scf_file:
                scf_content = scf_file.read()
            return self.cm_api_instance.cm_editor_eid_template_put(eid=delta_plan_id, body=scf_content)
        except IOError:
            raise PlanFileNotFound("File '{}' not found".format(scf_path))

    def get_staged_plans(self):
        return self.cm_api_instance.cm_plans_staged_get()

    def delete_staged_plan(self, plan_id):
        return self.cm_api_instance.cm_plans_staged_id_delete(plan_id)

    def validate_plan(self, plan_id, timeout):
        initialize_operation_request_body = InitializeOperationRequestBody("validate", False, self.configuration)
        operation_response = self.cm_api_instance.cm_plans_staged_id_jobs_post(
            plan_id, initialize_operation_request_body=initialize_operation_request_body)
        return self._wait_for_operation_to_finish(plan_id=plan_id, job_id=operation_response.job_id, timeout=timeout)

    def get_validation_results(self, plan_id=None, job_id=None):
        plan_id = plan_id if plan_id else self.current_plan_id
        job_id = job_id if job_id else self.current_job_id
        return self.cm_api_instance.cm_plans_staged_id_jobs_job_id_validation_result_get(plan_id, job_id)

    def get_validation_errors(self, plan_id=None, job_id=None):
        plan_id = plan_id if plan_id else self.current_plan_id
        job_id = job_id if job_id else self.current_job_id
        return self.cm_api_instance.cm_plans_staged_id_jobs_job_id_validation_result_errors_get_with_http_info(plan_id,
                                                                                                               job_id)

    def migrate_nidd(self, delta_plan_id, nidd_target_version, timeout):
        cm_editor_request_body = CmEditorTemplateJobPost(operation="migrate", target_version=nidd_target_version)
        operation_response = self.cm_api_instance.cm_editor_eid_template_jobs_post(
            delta_plan_id, cm_editor_template_job_post=cm_editor_request_body)
        return self._wait_for_nidd_migration_to_finish(delta_plan_id=delta_plan_id, job_id=operation_response.job_id,
                                                       timeout=timeout)

    def activate_plan(self, plan_id=None, timeout=60):
        plan_id = plan_id if plan_id else self.current_plan_id
        initialize_operation_request_body = InitializeOperationRequestBody("activate", False, self.configuration)
        operation_response = self.cm_api_instance.cm_plans_staged_id_jobs_post(
            plan_id, initialize_operation_request_body=initialize_operation_request_body)
        self._current_plan_id = plan_id
        self._current_job_id = operation_response.job_id
        return self._wait_for_operation_to_finish(plan_id=plan_id, job_id=operation_response.job_id, timeout=timeout)

    def create_new_delta_plan(self, source_plan, source_plan_id, timeout):
        new_editing_buffer_operation_request_body = CreateEditingBufferBody(source=source_plan,
                                                                            staged_id=source_plan_id)
        allocated_delta_plan = self.cm_api_instance.cm_editor_post(
            create_editing_buffer_body=new_editing_buffer_operation_request_body)
        cm_editor_operation_request_body = CmEditorJobPost(operation="load", source="active")
        operation_response = self.cm_api_instance.cm_editor_eid_jobs_post(
            allocated_delta_plan.eid, cm_editor_job_post=cm_editor_operation_request_body)
        self._wait_for_delta_plan_operation_to_finish(delta_plan_id=allocated_delta_plan.eid,
                                                      job_id=operation_response.job_id,
                                                      timeout=timeout)
        return allocated_delta_plan

    def get_staged_delta_plans(self):
        return self.cm_api_instance.cm_editor_get()

    def delete_delta_plan(self, delta_plan_id):
        return self.cm_api_instance.cm_editor_eid_delete(eid=delta_plan_id)

    def update_parameter_of_delta_plan(self, delta_plan_id, operation, dn, name, field, index, value):
        editor_modification = [
            EditorSingleParam(operation=operation, dn=dn, name=name, field=field, index=index, value=value)]
        return self.cm_api_instance.cm_editor_eid_parameters_patch(eid=delta_plan_id,
                                                                   editor_single_param=editor_modification)

    def update_object_of_delta_plan(self, delta_plan_id, body):
        return self.cm_api_instance.cm_editor_eid_objects_patch(eid=delta_plan_id, body=body)

    def activate_delta_plan(self, delta_plan_id, timeout):
        cm_editor_operation_request_body = CmEditorJobPost(operation="activate", source="active")
        operation_response = self.cm_api_instance.cm_editor_eid_jobs_post(
            delta_plan_id, cm_editor_job_post=cm_editor_operation_request_body)
        return self._wait_for_delta_plan_operation_to_finish(delta_plan_id=delta_plan_id,
                                                             job_id=operation_response.job_id,
                                                             timeout=timeout)

    def get_active_dist_names(self):
        return self.cm_api_instance.cm_plans_active_uids_get()

    def get_active_plan_file(self, timeout):
        job_completed_response = self.cm_api_instance.cm_plans_active_file_post()
        if job_completed_response.job_id:
            xml_plan_result = self._wait_for_active_plan_generate_to_finish(job_completed_response.job_id, timeout)
            xml_dict = {
                'file_name': job_completed_response.file_name,
                'xml_result': xml_plan_result
            }
            return xml_dict

    def get_delta_plan_file(self, delta_plan_id, content_type, timeout):
        job_completed_response = self.cm_api_instance.cm_editor_eid_file_post(
            eid=delta_plan_id, create_download_edited_plan_file={"contentType": content_type})
        if job_completed_response.job_id:
            xml_plan_result = self._wait_for_delta_plan_generate_to_finish(delta_plan_id,
                                                                           job_completed_response.job_id, timeout)
            xml_dict = {
                'file_name': job_completed_response.file_name,
                'xml_result': xml_plan_result
            }
            return xml_dict

    def _wait_for_active_plan_generate_to_finish(self, job_id, timeout):
        start_time = time.time()
        logging.info("Operation in progress ...")
        while time.time() - start_time < timeout:
            try:
                job_completed_response = self.cm_api_instance.cm_plans_active_file_job_id_get(job_id)
                if job_completed_response.location:
                    file_name = job_completed_response.location.split('/')[-1]
                    return self.cm_api_instance.cm_plans_active_file_job_id_result_get(job_id, file_name)
                else:
                    continue
            except MaxRetryError:
                logging.info("Cannot connect to ASIR Webem")
                time.sleep(1)
                continue
        else:
            raise AsirOperationTimeout(
                "Cannot finish job {} in {} seconds".format(job_id, timeout))

    def _wait_for_operation_to_finish(self, plan_id, job_id, timeout):  # noqa: C901
        start_time = time.time()
        logging.info("Operation in progress ...")
        while time.time() - start_time < timeout:
            try:
                job_completed_response = self.cm_api_instance.cm_plans_staged_id_jobs_job_id_get(plan_id, job_id)
                if job_completed_response.location:
                    return self.cm_api_instance.cm_plans_staged_id_jobs_job_id_validation_result_get(plan_id, job_id)
                else:
                    continue
            except MaxRetryError:
                logging.info("Cannot connect to ASIR Webem - waiting 1 sec for next attempt")
                time.sleep(1)
                continue
            except ApiException as e:
                if "503 Service Unavailable" in str(e):
                    logging.info("ASIR WebEM is Unavailable - waiting 10 sec for next attempt")
                    time.sleep(10)
                    continue
                else:
                    raise e
        else:
            raise AsirOperationTimeout(
                "Cannot finish job {} with plan {} in {} seconds".format(job_id, plan_id, timeout))

    def _wait_for_nidd_migration_to_finish(self, delta_plan_id, job_id, timeout):
        start_time = time.time()
        logging.info("Operation in progress ...")
        while time.time() - start_time < timeout:
            try:
                job_completed_response = self.cm_api_instance.cm_editor_eid_jobs_job_id_get(delta_plan_id, job_id)
                if job_completed_response.location:
                    return self.cm_api_instance.cm_editor_eid_template_jobs_job_id_migration_result_get(delta_plan_id,
                                                                                                        job_id)
                else:
                    continue
            except MaxRetryError:
                logging.info("Cannot connect to ASIR Webem")
                time.sleep(1)
                continue
        else:
            raise AsirOperationTimeout(
                "Cannot finish job {} with plan {} in {} seconds".format(job_id, delta_plan_id, timeout))

    def _wait_for_delta_plan_operation_to_finish(self, delta_plan_id, job_id, timeout):
        start_time = time.time()
        logging.info("Operation in progress ...")
        while time.time() - start_time < timeout:
            try:
                job_completed_response = self.cm_api_instance.cm_editor_eid_jobs_job_id_get(delta_plan_id, job_id)
                if job_completed_response.location:
                    return self.cm_api_instance.cm_editor_eid_jobs_job_id_validation_result_get(delta_plan_id, job_id)
                else:
                    continue
            except MaxRetryError:
                logging.info("Cannot connect to ASIR Webem")
                time.sleep(1)
                continue
        else:
            raise AsirOperationTimeout(
                "Cannot finish job {} with delta plan {} in {} seconds".format(job_id, delta_plan_id, timeout))

    def _wait_for_delta_plan_generate_to_finish(self, delta_plan_id, job_id, timeout):
        start_time = time.time()
        logging.info("Operation in progress ...")
        while time.time() - start_time < timeout:
            try:
                job_completed_response = self.cm_api_instance.cm_editor_eid_file_job_id_get(delta_plan_id, job_id)
                if job_completed_response.location:
                    file_name = job_completed_response.location.split('/')[-1]
                    return self.cm_api_instance.cm_editor_eid_file_job_id_result_get(delta_plan_id, job_id, file_name)
                else:
                    continue
            except MaxRetryError:
                logging.info("Cannot connect to ASIR Webem")
                time.sleep(1)
                continue
        else:
            raise AsirOperationTimeout(
                "Cannot finish job {} in {} seconds".format(job_id, timeout))
